namespace ArgentSea;
public class UnexpectedNullException : ApplicationException {   // public, not sealed
  UnexpectedNullException();
  UnexpectedNullException(string message);
  UnexpectedNullException(string message, Exception innerException);
  UnexpectedNullException(Type expectedType, string columnName); // "The database column {columnName} unexpectedly returned a “null” value and cannot be assigned to a {expectedType}."
  Type ExpectedType { get; }   // the non-nullable CLR type requested; null for the message-only constructors
  string ColumnName { get; }   // the parameter (or column) name; null for the message-only constructors
}
// Raised by the public typed DbParameter getters (GetLong, GetInteger, GetShort, GetByte, GetBoolean, GetDecimal, GetDateTime, GetDateTimeOffset, GetTimeSpan, GetDateOnly, GetTimeOnly) when the parameter value is DBNull; the parameter's ParameterName is passed as columnName.
// Callers can catch it by name and read ExpectedType/ColumnName. Callers that expect a possible null should use the nullable getter variants instead of catching.
